const FACE_ORDER=['U','R','F','D','L','B'];
const DEFAULT_COLORS={U:0xffffff,R:0xd92828,F:0x18a558,D:0xffd500,L:0xff7a00,B:0x2455d6};
const SOLVED='UUUUUUUUURRRRRRRRRFFFFFFFFFDDDDDDDDDLLLLLLLLLBBBBBBBBB';
export function createRubikExtension(THREE,hooks){
  let group=null,root=null,controls=[],state=null,turn=null,worker=null,requestId=0;
  const pending=new Map(),axisVectors={x:new THREE.Vector3(1,0,0),y:new THREE.Vector3(0,1,0),z:new THREE.Vector3(0,0,1)};
  function parse(source){const raw=String(source??'').trim(),config={algorithm:'',solution:'',facelets:SOLVED,speed:.42,autoplay:true,colors:{...DEFAULT_COLORS}},faces={};
    for(const line of raw.split(/\r?\n/)){const match=line.match(/^\s*([A-Za-z#]+)\s*:\s*(.*?)\s*$/);if(!match)continue;const rawKey=match[1],key=rawKey.toLowerCase(),value=match[2].trim();
      if(['algorithm','alg','scramble','moves'].includes(key))config.algorithm=value;else if(key==='solution')config.solution=value;else if(key==='facelets'&&/^[URFDLB]{54}$/i.test(value))config.facelets=value.toUpperCase();else if(key==='speed')config.speed=THREE.MathUtils.clamp(Number(value)||.42,.12,1.5);else if(key==='autoplay')config.autoplay=!/^(false|no|0)$/i.test(value);else if(/^[urfdlb]$/.test(key)&&value){if(/^[URFDLB]{9}$/i.test(value))faces[key.toUpperCase()]=value.toUpperCase();else if(/^#?[0-9a-f]{6}$/i.test(value))config.colors[key.toUpperCase()]=parseInt(value.replace('#',''),16);}else if(/^color[urfdlb]$/.test(key)&&/^#?[0-9a-f]{6}$/i.test(value))config.colors[key.at(-1).toUpperCase()]=parseInt(value.replace('#',''),16);else if(/^(URF|UFL|ULB|UBR|DFR|DLF|DBL|DRB)$/i.test(rawKey)&&/^[URFDLB]{3}$/i.test(value))config[rawKey.toUpperCase()]=value.toUpperCase();}
    if(Object.keys(faces).length===6)config.facelets=FACE_ORDER.map(face=>faces[face]).join('');
    const corners={URF:[8,9,20],UFL:[6,18,38],ULB:[0,36,47],UBR:[2,45,11],DFR:[29,26,15],DLF:[27,44,24],DBL:[33,53,42],DRB:[35,17,51]},chars=config.facelets.split('');for(const[name,indices]of Object.entries(corners)){if(config[name])indices.forEach((index,i)=>chars[index]=config[name][i]);}config.facelets=chars.join('');return config;}
  function drawPreview(canvas,config){const context=canvas.getContext('2d'),size=canvas.width/12,layout={U:[3,0],L:[0,3],F:[3,3],R:[6,3],B:[9,3],D:[3,6]};context.fillStyle='#070d18';context.fillRect(0,0,canvas.width,canvas.height);FACE_ORDER.forEach((face,fi)=>{const[ox,oy]=layout[face];for(let i=0;i<9;i++){const key=config.facelets[fi*9+i]||face;context.fillStyle='#'+(config.colors[key]??0x777777).toString(16).padStart(6,'0');context.fillRect((ox+i%3)*size+2,(oy+Math.floor(i/3))*size+2,size-4,size-4);}});}
  async function renderBlocks(container){for(const block of container.querySelectorAll('[data-note-rubik]')){let source=block.dataset.noteRubik||'';try{source=decodeURIComponent(source);}catch{}const canvas=document.createElement('canvas');canvas.width=720;canvas.height=540;canvas.dataset.noteRubikPreview='1';canvas.className='note-rubik-image';drawPreview(canvas,parse(source));block.replaceChildren(canvas);}}
  function stickerIndex(face,x,y,z){if(face==='U')return(z+1)*3+x+1;if(face==='D')return 27+(1-z)*3+x+1;if(face==='F')return 18+(1-y)*3+x+1;if(face==='B')return 45+(1-y)*3+1-x;if(face==='R')return 9+(1-y)*3+1-z;return 36+(1-y)*3+z+1;}
  function build(config){const cube=new THREE.Group(),cubies=[],gap=.044,body=new THREE.BoxGeometry(.039,.039,.039),stickerGeo=new THREE.PlaneGeometry(.032,.032),faces=[['U',0,1,0,-Math.PI/2,0,0],['D',0,-1,0,Math.PI/2,0,0],['F',0,0,1,0,0,0],['B',0,0,-1,0,Math.PI,0],['R',1,0,0,0,Math.PI/2,0],['L',-1,0,0,0,-Math.PI/2,0]];
    for(let x=-1;x<=1;x++)for(let y=-1;y<=1;y++)for(let z=-1;z<=1;z++){if(!x&&!y&&!z)continue;const cubie=new THREE.Group();cubie.position.set(x*gap,y*gap,z*gap);cubie.userData.grid=new THREE.Vector3(x,y,z);cubie.add(new THREE.Mesh(body,new THREE.MeshStandardMaterial({color:0x07090c,roughness:.78,metalness:.04})));for(const[face,nx,ny,nz,rx,ry,rz]of faces){if((nx&&x!==nx)||(ny&&y!==ny)||(nz&&z!==nz))continue;const key=config.facelets[stickerIndex(face,x,y,z)]||face,sticker=new THREE.Mesh(stickerGeo,new THREE.MeshBasicMaterial({color:config.colors[key]??0x777777,side:THREE.DoubleSide,toneMapped:false}));sticker.position.set(nx*.0205,ny*.0205,nz*.0205);sticker.rotation.set(rx,ry,rz);cubie.add(sticker);}cube.add(cubie);cubies.push(cubie);}cube.userData.cubies=cubies;return cube;}
  const tokens=value=>String(value??'').replace(/[(),]/g,' ').match(/[URFDLB](?:w)?(?:2|')?/g)||[];
  const inverse=move=>move.endsWith('2')?move:move.endsWith("'")?move.slice(0,-1):move+"'";
  function spec(token){const face=token[0],base={U:['y',1,-1],D:['y',-1,1],R:['x',1,-1],L:['x',-1,1],F:['z',1,-1],B:['z',-1,1]}[face];if(!base)return null;return{axis:base[0],layer:base[1],wide:token.includes('w'),angle:base[2]*Math.PI/2*(token.includes("'")?-1:1)*(token.includes('2')?2:1),duration:state.config.speed*(token.includes('2')?1.35:1)};}
  function start(move,record=true){if(!root||turn)return false;const moveSpec=spec(move);if(!moveSpec)return false;const pivot=new THREE.Group();root.add(pivot);const affected=root.userData.cubies.filter(c=>c.userData.grid[moveSpec.axis]===moveSpec.layer||(moveSpec.wide&&c.userData.grid[moveSpec.axis]===0));affected.forEach(c=>pivot.attach(c));turn={move,record,spec:moveSpec,pivot,affected,started:performance.now(),last:0};return true;}
  function finish(){const current=turn;if(!current)return;for(const cubie of current.affected){root.attach(cubie);cubie.position.set(Math.round(cubie.position.x/.044)*.044,Math.round(cubie.position.y/.044)*.044,Math.round(cubie.position.z/.044)*.044);cubie.userData.grid.set(Math.round(cubie.position.x/.044),Math.round(cubie.position.y/.044),Math.round(cubie.position.z/.044));}current.pivot.removeFromParent();if(current.record)state.history.push(current.move);turn=null;if(state.playing)next();}
  function update(time){if(!turn)return;const ratio=THREE.MathUtils.clamp((time-turn.started)/(turn.spec.duration*1000),0,1),eased=ratio<.5?2*ratio*ratio:1-Math.pow(-2*ratio+2,2)/2,angle=turn.spec.angle*eased;turn.pivot.rotateOnAxis(axisVectors[turn.spec.axis],angle-turn.last);turn.last=angle;if(ratio>=1)finish();}
  function next(){if(!state||turn)return;if(state.index>=state.sequence.length){state.playing=false;hooks.message('Rubik sequence finished.');return;}start(state.sequence[state.index++]);}
  function playing(value){if(!state)return;state.playing=value;if(value)next();hooks.message(value?'Rubik sequence playing.':'Rubik sequence paused.');}
  function step(delta){if(!state||turn)return;if(delta>0){if(state.index<state.sequence.length)start(state.sequence[state.index++]);}else if(state.history.length){const move=state.history.pop();state.index=Math.max(0,state.index-1);start(inverse(move),false);}}
  function reset(){if(!state||!root)return;turn=null;root.removeFromParent();root=build(state.config);root.position.y=.012;root.rotation.set(-.35,.55,0);root.scale.setScalar(1.45);group.add(root);state.index=0;state.history=[];state.playing=false;}
  function ensureWorker(){if(worker)return worker;const source=`importScripts('/vendor/cubejs/cube.js','/vendor/cubejs/solve.js');let ready=false;onmessage=e=>{const{id,facelets,algorithm}=e.data;try{if(!ready){Cube.initSolver();ready=true}const cube=Cube.fromString(facelets);if(algorithm)cube.move(algorithm);postMessage({id,solution:cube.solve(),facelets:cube.asString()})}catch(error){postMessage({id,error:String(error&&error.message||error)})}}`;worker=new Worker(URL.createObjectURL(new Blob([source],{type:'text/javascript'})));worker.onmessage=({data})=>{const item=pending.get(data.id);if(!item)return;pending.delete(data.id);data.error?item.reject(new Error(data.error)):item.resolve(data);};return worker;}
  function workerSolve(facelets,algorithm){return new Promise((resolve,reject)=>{const id=++requestId;pending.set(id,{resolve,reject});ensureWorker().postMessage({id,facelets,algorithm});});}
  async function solve(){if(!state)return;hooks.message('Solving Rubik cube outside the XR thread…');try{const result=await workerSolve(state.config.facelets,state.history.join(' '));state.sequence=tokens(result.solution);state.index=0;state.playing=true;next();hooks.message(`Rubik solution ready · ${state.sequence.length} moves.`);}catch(error){hooks.message(`Invalid or unsolvable cube: ${error.message}`);}}
  function addControl(action,x,label,color=0x75a7ff){const control=new THREE.Mesh(new THREE.CircleGeometry(.015,16),new THREE.MeshBasicMaterial({color,depthTest:true,depthWrite:true,toneMapped:false}));control.position.set(x,-hooks.height/2+.028,.036);control.renderOrder=1013;control.userData.noteAction=action;control.userData.highlightScale=false;const canvas=document.createElement('canvas');canvas.width=64;canvas.height=64;const context=canvas.getContext('2d');context.fillStyle='#07111f';context.font='bold 31px system-ui';context.textAlign='center';context.textBaseline='middle';context.fillText(label,32,33);const texture=new THREE.CanvasTexture(canvas),icon=new THREE.Mesh(new THREE.PlaneGeometry(.022,.022),new THREE.MeshBasicMaterial({map:texture,transparent:true,depthTest:true,depthWrite:false,toneMapped:false}));icon.position.z=.003;icon.raycast=()=>{};control.add(icon);group.add(control);controls.push(control);hooks.addControl(control);}
  function dispose(){hooks.removeControls(controls);hooks.unregister(group,false);if(group){group.removeFromParent();group.traverse(object=>{object.geometry?.dispose?.();object.material?.map?.dispose?.();object.material?.dispose?.();});}group=root=state=turn=null;controls=[];hooks.layout();}
  function open(source){dispose();const config=parse(source);group=new THREE.Group();group.name='rubik-window';const panel=new THREE.Mesh(hooks.geometry(hooks.width,hooks.height,.022,24),new THREE.MeshBasicMaterial({color:0x080d17,transparent:true,opacity:.94,depthTest:true,depthWrite:true,toneMapped:false}));hooks.round(panel);panel.raycast=()=>{};group.add(panel);root=build(config);root.position.y=.012;root.rotation.set(-.35,.55,0);root.scale.setScalar(1.45);group.add(root);state={config,sequence:tokens(config.solution||config.algorithm),index:0,history:[],playing:false};addControl('rubik-prev',-.09,'‹');addControl('rubik-toggle',-.045,'▶',0x63e6be);addControl('rubik-next',0,'›');addControl('rubik-solve',.045,'✓',0xffd166);addControl('rubik-reset',.09,'↻');addControl('rubik-close',hooks.width/2-.028,'×',0xff6b6b);hooks.register(group,hooks.width);if(config.autoplay&&state.sequence.length)playing(true);else hooks.message('Interactive Rubik cube ready.');}
  function handle(action){if(action==='rubik-prev')step(-1);else if(action==='rubik-next')step(1);else if(action==='rubik-toggle')playing(!state?.playing);else if(action==='rubik-solve')void solve();else if(action==='rubik-reset')reset();else if(action==='rubik-close'){dispose();hooks.message('Rubik cube closed.');}else return false;return true;}
  return{parse,drawPreview,renderBlocks,open,dispose,update,handle};
}
